<?php foreach($data['email-stored'] as $mail_record): ?><tr data-owner="<?=$escape($mail_record['owner'])?>"><td><?=$escape($mail_record['owner'].' / '.$mail_record['recipient'])?><p><?=$escape($mail_record['subject']??'(No subject)')?><br><?=$escape($mail_record['sender']??'')?></p></td><td><?=$escape(gmdate('Y-m-d H:i:s',(int)$mail_record['created']))?> UTC</td><td><?=$escape(str_replace('_',' ',$mail_record['status']))?></td><td>
<?php if($data['context']['admin'] && $mail_record['status']==='quarantined' && !empty($mail_record['review_selectable'])): ?>
<form class="cs-review-email-deliver" data-delivery="<?=$escape($mail_record['id'])?>"><label>Delivery reason <input class="form-control" name="note" required maxlength="1000" placeholder="Reason for delivering this email"></label><button class="button" type="submit">Deliver anyway</button><p class="cs-review-email-status" role="status" aria-live="polite"></p></form>
<?php endif ?></td></tr><?php endforeach ?>
